import base64, gzip, hashlib, io, json, os, re, stat, subprocess, tarfile
from pathlib import Path, PurePosixPath
EXPERIMENT_ID = 'zhenjiang_continuous_ukf_20260911_001'
REMOTE_ROOT = '/data1/home/sunyiq/zhenjiang_continuous_ukf_20260911_001'
SCHEMA_VERSION = 'zhenjiang-continuous-ukf-bundle-v3'
SLURM = 'run/scripts/hpc/zhenjiang_continuous_ukf_v3.slurm'
def sha256(data):
    return hashlib.sha256(data).hexdigest()

def json_bytes(value):
    return (json.dumps(value, sort_keys=True, ensure_ascii=False,
                       separators=(',', ':'), allow_nan=False) + '\n').encode('utf-8')

def strict_json(data):
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError('duplicate JSON key')
            result[key] = value
        return result
    return json.loads(data, object_pairs_hook=pairs)

def safe_name(name):
    if not isinstance(name, str) or not name or '\\' in name or ':' in name:
        raise ValueError('invalid relative member name')
    parts = name.split('/')
    if any(part in ('', '.', '..') for part in parts) or PurePosixPath(name).is_absolute():
        raise ValueError('unsafe relative member name')
    return name

def safe_path(path):
    path = Path(path)
    if '..' in path.parts:
        raise ValueError('parent traversal forbidden')
    path = path.absolute()
    for item in (path, *path.parents):
        if item.is_symlink():
            raise ValueError('symlinks forbidden: ' + str(item))
        if item.exists() and getattr(item.lstat(), 'st_file_attributes', 0) & 1024:
            raise ValueError('Windows reparse point forbidden')
    return path

def read_regular(path):
    path = safe_path(path)
    with path.open('rb') as stream:
        if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
            raise ValueError('not a regular file')
        return stream.read()

def manifest_entries(manifest):
    document = strict_json(manifest)
    fixed = dict(schema_version=SCHEMA_VERSION, experiment_id=EXPERIMENT_ID,
                 remote_root=REMOTE_ROOT, formal_data_included=False,
                 checkpoint_data_included=False, git_metadata_included=False)
    if not isinstance(document, dict) or set(document) != {*fixed, 'source_files'}:
        raise ValueError('invalid manifest schema')
    for key, value in fixed.items():
        if document[key] != value or type(document[key]) is not type(value):
            raise ValueError('manifest identity mismatch: ' + key)
    entries = {}
    for entry in document['source_files']:
        if not isinstance(entry, dict) or set(entry) != {'relative_path', 'byte_count', 'sha256'}:
            raise ValueError('invalid manifest entry')
        name = safe_name(entry['relative_path'])
        if name == 'bundle_manifest.json' or name in entries:
            raise ValueError('duplicate or recursive manifest member')
        if type(entry['byte_count']) is not int or entry['byte_count'] < 0:
            raise ValueError('invalid byte count')
        if not isinstance(entry['sha256'], str) or not re.fullmatch('[0-9a-f]{64}', entry['sha256']):
            raise ValueError('invalid SHA256')
        entries[name] = entry
    if not entries or list(entries) != sorted(entries):
        raise ValueError('empty or unsorted manifest')
    for name in entries:
        if any(str(parent) in entries for parent in PurePosixPath(name).parents):
            raise ValueError('file and directory name collision')
    return entries

def check_identity(data, entry):
    if len(data) != entry['byte_count'] or sha256(data) != entry['sha256']:
        raise ValueError('file byte identity mismatch')

def verify_bundle_bytes(payload, manifest):
    entries = manifest_entries(manifest)
    files = {}
    tar_bytes = gzip.decompress(payload)
    # tarfile hides PAX/GNU extension headers during iteration. Inspect physical
    # headers too, so non-regular metadata/link headers cannot escape validation.
    offset = 0
    while offset + 512 <= len(tar_bytes) and tar_bytes[offset:offset + 512] != bytes(512):
        header = tar_bytes[offset:offset + 512]
        if header[156:157] not in (b'0', b'\0'):
            raise ValueError('non-regular physical tar header')
        try:
            size = int(header[124:136].rstrip(b'\0 ').lstrip(b' ') or b'0', 8)
        except ValueError as error:
            raise ValueError('invalid tar size') from error
        if size < 0:
            raise ValueError('invalid tar size')
        offset += 512 + ((size + 511) // 512) * 512
    if offset + 1024 > len(tar_bytes) or any(tar_bytes[offset:]):
        raise ValueError('invalid tar terminator or trailing content')
    with tarfile.open(fileobj=io.BytesIO(tar_bytes), mode='r:') as archive:
        for member in archive:
            name = safe_name(member.name)
            if not member.isfile() or member.type not in (tarfile.REGTYPE, tarfile.AREGTYPE):
                raise ValueError('only regular tar members allowed')
            if name in files or name not in {*entries, 'bundle_manifest.json'}:
                raise ValueError('duplicate or unknown tar member')
            expected_size = len(manifest) if name == 'bundle_manifest.json' else entries[name]['byte_count']
            if member.size != expected_size:
                raise ValueError('tar member size mismatch')
            data = archive.extractfile(member).read()
            if name == 'bundle_manifest.json':
                if data != manifest:
                    raise ValueError('external and internal manifest differ')
            else:
                check_identity(data, entries[name])
            files[name] = data
    if set(files) != {*entries, 'bundle_manifest.json'}:
        raise ValueError('missing tar members')
    del files['bundle_manifest.json']
    return files

def parse_submission(text):
    match = re.fullmatch(r'Submitted batch job ([1-9][0-9]*)\n?', text)
    if match is None:
        raise ValueError('submission receipt must be unique and exact')
    return int(match.group(1))

def write_exclusive(path, data):
    with safe_path(path).open('xb') as stream:
        stream.write(data)
        stream.flush()
        os.fsync(stream.fileno())

def deploy_once(payload, manifest, submit=subprocess.run):
    files = verify_bundle_bytes(payload, manifest)
    root = safe_path(REMOTE_ROOT)
    # No parent creation, replacement, cleanup, retry or existing-root resume.
    root.mkdir(exist_ok=False)
    # The formal runner exclusively reserves children below this deployment-owned
    # parent with parents=False; create the parent before any submission attempt.
    (root / 'runs').mkdir(exist_ok=False)
    for name, data in sorted({**files, 'bundle_manifest.json': manifest}.items()):
        target = safe_path(root / name)
        target.parent.mkdir(parents=True, exist_ok=True)
        write_exclusive(target, data)
    (root / 'logs').mkdir()
    attempt = root / 'evidence/submission/attempt_001'
    attempt.mkdir(parents=True, exist_ok=False)
    command = ['sbatch', str(root / SLURM), sha256(manifest)]
    write_exclusive(attempt / 'requested.json', json_bytes(dict(command=command, maximum_submissions=1)))
    try:
        result = submit(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)
    except Exception as error:
        write_exclusive(attempt / 'failure.json', json_bytes(dict(error=str(error), retry_allowed=False)))
        raise
    write_exclusive(attempt / 'stdout.txt', result.stdout)
    write_exclusive(attempt / 'stderr.txt', result.stderr)
    write_exclusive(attempt / 'exit_status.json', json_bytes(dict(returncode=result.returncode)))
    try:
        if result.returncode != 0 or result.stderr:
            raise ValueError('sbatch failed or returned ambiguous stderr; no retry')
        job_id = parse_submission(result.stdout.decode('ascii'))
    except Exception as error:
        write_exclusive(attempt / 'failure.json', json_bytes(dict(error=str(error), retry_allowed=False)))
        raise
    write_exclusive(attempt / 'submission_receipt.json', json_bytes(dict(job_id=job_id)))
    return job_id

payload = base64.b64decode('', validate=True)
manifest = base64.b64decode('', validate=True)
check_identity(payload, {'byte_count': 184829, 'sha256': '12cf8c6839d7cebb5db132448e7abb5f6337d3271c6ebb887498e42044aebfd1'})
check_identity(manifest, {'byte_count': 6185, 'sha256': '67bfe19b26abcd2e8b0eb5cb9b72aacf6e838d12ddde8014a6ef4b943252437f'})
print("Submitted batch job", deploy_once(payload, manifest))
ZJ_CUKF_DEPLOY_PY
